            f_aptr <= a_base_w; f_atile <= a_base_w;
            f_bptr <= b_base_w; f_btile <= b_base_w;
            c_ptr <= c_base_w; c_tile <= c_base_w; c_rowbase <= c_base_w;
        end else begin
            if (f_issue) begin
                if (f_lastk) begin
                    if (f_wrap) begin
                        f_atile <= f_atile + 11'd1; f_aptr <= f_atile + 11'd1;
                        f_btile <= b_base_w; f_bptr <= b_base_w;
                    end else begin
                        f_aptr <= f_atile;
                        f_btile <= f_btile + 12'd1; f_bptr <= f_btile + 12'd1;
                    end
                end else begin
                    f_aptr <= f_aptr + a_ld_w; f_bptr <= f_bptr + b_ld_w;
                end
            end
            if (core_ov) begin
                if (core_ol) begin
                    if (d_wrap) begin
                        c_rowbase <= c_rowbase + c_tilestep;
                        c_tile <= c_rowbase + c_tilestep; c_ptr <= c_rowbase + c_tilestep;
                    end else begin
                        c_tile <= c_tile + 10'd1; c_ptr <= c_tile + 10'd1;
                    end
                end else begin
                    c_ptr <= c_ptr + c_ld_w;
                end
            end
        end
    end

    // ---- CSR writes, status flags, top-level state ----
    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE; mode_q <= 2'd0; m_q <= 16'd0; k_q <= 16'd0; n_q <= 16'd0;
            a_base_w <= 11'd0; a_ld_w <= 11'd0;
            b_base_w <= 12'd0; b_ld_w <= 12'd0;
            c_base_w <= 10'd0; c_ld_w <= 10'd0;
            done_q <= 1'b0; err_cfg_q <= 1'b0; err_busy_q <= 1'b0; cycles_q <= 32'd0;
        end else begin
            if (busy) cycles_q <= cycles_q + 32'd1;
            if (req && busy && (wb_we || region != R_CSR)) err_busy_q <= 1'b1;
            if (csr_wr) begin
                case (csr_idx)
                    4'd2: begin
                        if (wb_dat_w[1]) begin done_q <= 1'b0; err_cfg_q <= 1'b0; err_busy_q <= 1'b0; end
                        if (wb_dat_w[0]) begin
                            if (dims_ok) begin done_q <= 1'b0; cycles_q <= 32'd0; st <= S_SETUP; end
                            else err_cfg_q <= 1'b1;
                        end
                    end
                    4'd4:  mode_q <= wb_dat_w[1:0];
                    4'd5:  m_q <= wb_dat_w[15:0];
                    4'd6:  k_q <= wb_dat_w[15:0];
                    4'd7:  n_q <= wb_dat_w[15:0];
                    4'd8:  a_base_w <= wb_dat_w[13:3];
                    4'd9:  a_ld_w   <= wb_dat_w[13:3];
                    4'd10: b_base_w <= wb_dat_w[14:3];
                    4'd11: b_ld_w   <= wb_dat_w[14:3];
                    4'd12: c_base_w <= wb_dat_w[14:5];
                    4'd13: c_ld_w   <= wb_dat_w[14:5];
                    default: ;
                endcase
            end
            case (st)
                S_SETUP: st <= S_RUN;
                S_RUN: if (core_ov && core_ol && d_last) st <= S_TAIL;
                S_TAIL: begin st <= S_IDLE; done_q <= 1'b1; end  // last C write lands
                default: ;
            endcase
        end
    end

    // ---- A buffer: 8 byte lanes x 2048 rows ----
    wire [10:0] bus_arow = wb_adr[11:1];
    wire [10:0] a_raddr = busy ? f_aptr : bus_arow;
    wire a_bwr = wr && !busy && (region == R_A);
    reg [7:0] amem_0 [0:2047];
    reg [7:0] a_rd_0;
    always @(posedge clk) begin
        if (a_bwr && (wb_adr[0:0] == 1'd0) && wb_sel[0]) amem_0[bus_arow] <= wb_dat_w[7:0];
        a_rd_0 <= amem_0[a_raddr];
    end
    reg [7:0] amem_1 [0:2047];
    reg [7:0] a_rd_1;
    always @(posedge clk) begin
        if (a_bwr && (wb_adr[0:0] == 1'd0) && wb_sel[1]) amem_1[bus_arow] <= wb_dat_w[15:8];
        a_rd_1 <= amem_1[a_raddr];
    end
    reg [7:0] amem_2 [0:2047];
    reg [7:0] a_rd_2;
    always @(posedge clk) begin
        if (a_bwr && (wb_adr[0:0] == 1'd0) && wb_sel[2]) amem_2[bus_arow] <= wb_dat_w[23:16];
        a_rd_2 <= amem_2[a_raddr];
    end
    reg [7:0] amem_3 [0:2047];
    reg [7:0] a_rd_3;
    always @(posedge clk) begin
        if (a_bwr && (wb_adr[0:0] == 1'd0) && wb_sel[3]) amem_3[bus_arow] <= wb_dat_w[31:24];
        a_rd_3 <= amem_3[a_raddr];
    end
    reg [7:0] amem_4 [0:2047];
    reg [7:0] a_rd_4;
    always @(posedge clk) begin
        if (a_bwr && (wb_adr[0:0] == 1'd1) && wb_sel[0]) amem_4[bus_arow] <= wb_dat_w[7:0];
        a_rd_4 <= amem_4[a_raddr];
    end
    reg [7:0] amem_5 [0:2047];
    reg [7:0] a_rd_5;
    always @(posedge clk) begin
        if (a_bwr && (wb_adr[0:0] == 1'd1) && wb_sel[1]) amem_5[bus_arow] <= wb_dat_w[15:8];
        a_rd_5 <= amem_5[a_raddr];
    end
    reg [7:0] amem_6 [0:2047];
    reg [7:0] a_rd_6;
    always @(posedge clk) begin
        if (a_bwr && (wb_adr[0:0] == 1'd1) && wb_sel[2]) amem_6[bus_arow] <= wb_dat_w[23:16];
        a_rd_6 <= amem_6[a_raddr];
    end
    reg [7:0] amem_7 [0:2047];
    reg [7:0] a_rd_7;
    always @(posedge clk) begin
        if (a_bwr && (wb_adr[0:0] == 1'd1) && wb_sel[3]) amem_7[bus_arow] <= wb_dat_w[31:24];
        a_rd_7 <= amem_7[a_raddr];
    end

    // ---- B buffer: 8 byte lanes x 4096 rows ----
    wire [11:0] bus_brow = wb_adr[12:1];
    wire [11:0] b_raddr = busy ? f_bptr : bus_brow;
    wire b_bwr = wr && !busy && (region == R_B);
    reg [7:0] bmem_0 [0:4095];
    reg [7:0] b_rd_0;
    always @(posedge clk) begin
        if (b_bwr && (wb_adr[0:0] == 1'd0) && wb_sel[0]) bmem_0[bus_brow] <= wb_dat_w[7:0];
        b_rd_0 <= bmem_0[b_raddr];
    end
    reg [7:0] bmem_1 [0:4095];
    reg [7:0] b_rd_1;
    always @(posedge clk) begin
        if (b_bwr && (wb_adr[0:0] == 1'd0) && wb_sel[1]) bmem_1[bus_brow] <= wb_dat_w[15:8];
        b_rd_1 <= bmem_1[b_raddr];
    end
    reg [7:0] bmem_2 [0:4095];
    reg [7:0] b_rd_2;
    always @(posedge clk) begin
        if (b_bwr && (wb_adr[0:0] == 1'd0) && wb_sel[2]) bmem_2[bus_brow] <= wb_dat_w[23:16];
        b_rd_2 <= bmem_2[b_raddr];
    end
    reg [7:0] bmem_3 [0:4095];
    reg [7:0] b_rd_3;
    always @(posedge clk) begin
        if (b_bwr && (wb_adr[0:0] == 1'd0) && wb_sel[3]) bmem_3[bus_brow] <= wb_dat_w[31:24];
        b_rd_3 <= bmem_3[b_raddr];
    end
    reg [7:0] bmem_4 [0:4095];
    reg [7:0] b_rd_4;
    always @(posedge clk) begin
        if (b_bwr && (wb_adr[0:0] == 1'd1) && wb_sel[0]) bmem_4[bus_brow] <= wb_dat_w[7:0];
        b_rd_4 <= bmem_4[b_raddr];
    end
    reg [7:0] bmem_5 [0:4095];
    reg [7:0] b_rd_5;
    always @(posedge clk) begin
        if (b_bwr && (wb_adr[0:0] == 1'd1) && wb_sel[1]) bmem_5[bus_brow] <= wb_dat_w[15:8];
        b_rd_5 <= bmem_5[b_raddr];
    end
    reg [7:0] bmem_6 [0:4095];
    reg [7:0] b_rd_6;
    always @(posedge clk) begin
        if (b_bwr && (wb_adr[0:0] == 1'd1) && wb_sel[2]) bmem_6[bus_brow] <= wb_dat_w[23:16];
        b_rd_6 <= bmem_6[b_raddr];
    end
    reg [7:0] bmem_7 [0:4095];
    reg [7:0] b_rd_7;
    always @(posedge clk) begin
        if (b_bwr && (wb_adr[0:0] == 1'd1) && wb_sel[3]) bmem_7[bus_brow] <= wb_dat_w[31:24];
        b_rd_7 <= bmem_7[b_raddr];
    end

    // ---- operand stage: issue (cycle t) -> BRAM (t+1) -> register (t+2) ----
    always @(posedge clk) begin
        a_q <= {a_rd_7, a_rd_6, a_rd_5, a_rd_4, a_rd_3, a_rd_2, a_rd_1, a_rd_0};
        b_q <= {b_rd_7, b_rd_6, b_rd_5, b_rd_4, b_rd_3, b_rd_2, b_rd_1, b_rd_0};
    end

    // ---- C buffer: 8 word lanes x 1024 rows ----
    wire [9:0] bus_crow = wb_adr[12:3];
    wire [9:0] c_raddr = busy ? (core_ov ? c_ptr + c_ld_w : c_ptr) : bus_crow;
    // Drain write is pipelined one cycle: row r (and its old C value for ACCUM)
    // is registered in drain cycle r and written in the next cycle.
    reg  [9:0] cw_addr_q;
    reg  [7:0] cw_we_q;
    reg  [255:0] row_q;
    wire [9:0] c_waddr = busy ? cw_addr_q : bus_crow;
    wire c_bwr = wr && !busy && (region == R_C);
    wire [3:0] c_be = busy ? 4'hf : wb_sel;
    wire d_wr = core_ov && d_rowok;
    always @(posedge clk) begin
        if (rst) cw_we_q <= 8'd0;
        else cw_we_q <= d_wr ? d_lane : 8'd0;
        cw_addr_q <= c_ptr;
        row_q <= core_row;
    end
    reg [31:0] cmem_0 [0:1023];
    reg [31:0] c_rd_0, crd_q_0;
    always @(posedge clk) crd_q_0 <= mode_q[0] ? c_rd_0 : 32'd0;
    wire [31:0] c_sum_0 = row_q[31:0] + crd_q_0;
    wire [31:0] c_wd_0 = busy ? c_sum_0 : wb_dat_w;
    wire c_we_0 = busy ? cw_we_q[0] : (c_bwr && (wb_adr[2:0] == 3'd0));
    always @(posedge clk) begin
        if (c_we_0) begin
            if (c_be[0]) cmem_0[c_waddr][7:0] <= c_wd_0[7:0];
            if (c_be[1]) cmem_0[c_waddr][15:8] <= c_wd_0[15:8];
            if (c_be[2]) cmem_0[c_waddr][23:16] <= c_wd_0[23:16];
            if (c_be[3]) cmem_0[c_waddr][31:24] <= c_wd_0[31:24];
        end
        c_rd_0 <= cmem_0[c_raddr];
    end
    reg [31:0] cmem_1 [0:1023];
    reg [31:0] c_rd_1, crd_q_1;
    always @(posedge clk) crd_q_1 <= mode_q[0] ? c_rd_1 : 32'd0;
    wire [31:0] c_sum_1 = row_q[63:32] + crd_q_1;
    wire [31:0] c_wd_1 = busy ? c_sum_1 : wb_dat_w;
    wire c_we_1 = busy ? cw_we_q[1] : (c_bwr && (wb_adr[2:0] == 3'd1));
    always @(posedge clk) begin
        if (c_we_1) begin
            if (c_be[0]) cmem_1[c_waddr][7:0] <= c_wd_1[7:0];
            if (c_be[1]) cmem_1[c_waddr][15:8] <= c_wd_1[15:8];
            if (c_be[2]) cmem_1[c_waddr][23:16] <= c_wd_1[23:16];
            if (c_be[3]) cmem_1[c_waddr][31:24] <= c_wd_1[31:24];
        end
        c_rd_1 <= cmem_1[c_raddr];
    end
    reg [31:0] cmem_2 [0:1023];
    reg [31:0] c_rd_2, crd_q_2;
    always @(posedge clk) crd_q_2 <= mode_q[0] ? c_rd_2 : 32'd0;
    wire [31:0] c_sum_2 = row_q[95:64] + crd_q_2;
    wire [31:0] c_wd_2 = busy ? c_sum_2 : wb_dat_w;
    wire c_we_2 = busy ? cw_we_q[2] : (c_bwr && (wb_adr[2:0] == 3'd2));
    always @(posedge clk) begin
        if (c_we_2) begin
            if (c_be[0]) cmem_2[c_waddr][7:0] <= c_wd_2[7:0];
            if (c_be[1]) cmem_2[c_waddr][15:8] <= c_wd_2[15:8];
            if (c_be[2]) cmem_2[c_waddr][23:16] <= c_wd_2[23:16];
            if (c_be[3]) cmem_2[c_waddr][31:24] <= c_wd_2[31:24];
        end
        c_rd_2 <= cmem_2[c_raddr];
    end
    reg [31:0] cmem_3 [0:1023];
    reg [31:0] c_rd_3, crd_q_3;
    always @(posedge clk) crd_q_3 <= mode_q[0] ? c_rd_3 : 32'd0;
    wire [31:0] c_sum_3 = row_q[127:96] + crd_q_3;
    wire [31:0] c_wd_3 = busy ? c_sum_3 : wb_dat_w;
    wire c_we_3 = busy ? cw_we_q[3] : (c_bwr && (wb_adr[2:0] == 3'd3));
    always @(posedge clk) begin
        if (c_we_3) begin
            if (c_be[0]) cmem_3[c_waddr][7:0] <= c_wd_3[7:0];
            if (c_be[1]) cmem_3[c_waddr][15:8] <= c_wd_3[15:8];
            if (c_be[2]) cmem_3[c_waddr][23:16] <= c_wd_3[23:16];
            if (c_be[3]) cmem_3[c_waddr][31:24] <= c_wd_3[31:24];
        end
        c_rd_3 <= cmem_3[c_raddr];
    end
    reg [31:0] cmem_4 [0:1023];
    reg [31:0] c_rd_4, crd_q_4;
    always @(posedge clk) crd_q_4 <= mode_q[0] ? c_rd_4 : 32'd0;
    wire [31:0] c_sum_4 = row_q[159:128] + crd_q_4;
    wire [31:0] c_wd_4 = busy ? c_sum_4 : wb_dat_w;
    wire c_we_4 = busy ? cw_we_q[4] : (c_bwr && (wb_adr[2:0] == 3'd4));
    always @(posedge clk) begin
        if (c_we_4) begin
            if (c_be[0]) cmem_4[c_waddr][7:0] <= c_wd_4[7:0];
            if (c_be[1]) cmem_4[c_waddr][15:8] <= c_wd_4[15:8];
            if (c_be[2]) cmem_4[c_waddr][23:16] <= c_wd_4[23:16];
            if (c_be[3]) cmem_4[c_waddr][31:24] <= c_wd_4[31:24];
        end
        c_rd_4 <= cmem_4[c_raddr];
    end
    reg [31:0] cmem_5 [0:1023];
    reg [31:0] c_rd_5, crd_q_5;
    always @(posedge clk) crd_q_5 <= mode_q[0] ? c_rd_5 : 32'd0;
    wire [31:0] c_sum_5 = row_q[191:160] + crd_q_5;
    wire [31:0] c_wd_5 = busy ? c_sum_5 : wb_dat_w;
    wire c_we_5 = busy ? cw_we_q[5] : (c_bwr && (wb_adr[2:0] == 3'd5));
    always @(posedge clk) begin
        if (c_we_5) begin
            if (c_be[0]) cmem_5[c_waddr][7:0] <= c_wd_5[7:0];
            if (c_be[1]) cmem_5[c_waddr][15:8] <= c_wd_5[15:8];
            if (c_be[2]) cmem_5[c_waddr][23:16] <= c_wd_5[23:16];
            if (c_be[3]) cmem_5[c_waddr][31:24] <= c_wd_5[31:24];
        end
        c_rd_5 <= cmem_5[c_raddr];
    end
    reg [31:0] cmem_6 [0:1023];
    reg [31:0] c_rd_6, crd_q_6;
    always @(posedge clk) crd_q_6 <= mode_q[0] ? c_rd_6 : 32'd0;
    wire [31:0] c_sum_6 = row_q[223:192] + crd_q_6;
    wire [31:0] c_wd_6 = busy ? c_sum_6 : wb_dat_w;
    wire c_we_6 = busy ? cw_we_q[6] : (c_bwr && (wb_adr[2:0] == 3'd6));
    always @(posedge clk) begin
        if (c_we_6) begin
            if (c_be[0]) cmem_6[c_waddr][7:0] <= c_wd_6[7:0];
            if (c_be[1]) cmem_6[c_waddr][15:8] <= c_wd_6[15:8];
            if (c_be[2]) cmem_6[c_waddr][23:16] <= c_wd_6[23:16];
            if (c_be[3]) cmem_6[c_waddr][31:24] <= c_wd_6[31:24];
        end
        c_rd_6 <= cmem_6[c_raddr];
    end
    reg [31:0] cmem_7 [0:1023];
    reg [31:0] c_rd_7, crd_q_7;
    always @(posedge clk) crd_q_7 <= mode_q[0] ? c_rd_7 : 32'd0;
    wire [31:0] c_sum_7 = row_q[255:224] + crd_q_7;
    wire [31:0] c_wd_7 = busy ? c_sum_7 : wb_dat_w;
    wire c_we_7 = busy ? cw_we_q[7] : (c_bwr && (wb_adr[2:0] == 3'd7));
    always @(posedge clk) begin
        if (c_we_7) begin
            if (c_be[0]) cmem_7[c_waddr][7:0] <= c_wd_7[7:0];
            if (c_be[1]) cmem_7[c_waddr][15:8] <= c_wd_7[15:8];
            if (c_be[2]) cmem_7[c_waddr][23:16] <= c_wd_7[23:16];
            if (c_be[3]) cmem_7[c_waddr][31:24] <= c_wd_7[31:24];
        end
        c_rd_7 <= cmem_7[c_raddr];
    end

    // ---- read data: from registers (csr_q) and BRAM output registers only ----
    reg [31:0] a_word, b_word, c_word;
    always @(*) begin
        case (lane_q[0:0])
            1'd0: begin a_word = {a_rd_3, a_rd_2, a_rd_1, a_rd_0}; b_word = {b_rd_3, b_rd_2, b_rd_1, b_rd_0}; end
            1'd1: begin a_word = {a_rd_7, a_rd_6, a_rd_5, a_rd_4}; b_word = {b_rd_7, b_rd_6, b_rd_5, b_rd_4}; end
            default: begin a_word = 32'd0; b_word = 32'd0; end
        endcase
        case (lane_q)
            3'd0: c_word = c_rd_0;
            3'd1: c_word = c_rd_1;
            3'd2: c_word = c_rd_2;
            3'd3: c_word = c_rd_3;
            3'd4: c_word = c_rd_4;
            3'd5: c_word = c_rd_5;
            3'd6: c_word = c_rd_6;
            3'd7: c_word = c_rd_7;
            default: c_word = 32'd0;
        endcase
    end
    assign wb_dat_r = rzero_q ? 32'd0 :
                      (rreg_q == R_CSR) ? csr_q :
                      (rreg_q == R_A)   ? a_word :
                      (rreg_q == R_B)   ? b_word : c_word;
endmodule

`default_nettype wire
